template <class... Applied>
class ConnBuilder {
  ConnState state_;
public:
  [[nodiscard]] auto host(std::string h) && {
    static_assert(!(std::is_same_v<HostTag, Applied> || ...), "already set");
    state_.host = std::move(h);
    return ConnBuilder<HostTag, Applied...>{std::move(state_)};
  }
  [[nodiscard]] Conn build() &&
      requires (contains<HostTag, Applied...> && contains<PortTag, Applied...>)
  { return Conn{std::move(state_)}; }
};
